  ln(svg,96,yTop,96,yBottom,C.muted,1);ln(svg,96,yBottom,566,yBottom,C.muted,1);
  const yAxis=txt(svg,20,(yTop+yBottom)/2,"Outcome (illustrative units)",C.ink,8,"middle","600");yAxis.setAttribute("transform",`rotate(-90 20 ${(yTop+yBottom)/2})`);
  txt(svg,x0,226,"Pre",C.ink,9,"middle","600");txt(svg,x1,226,"Post",C.ink,9,"middle","600");txt(svg,(x0+x1)/2,242,"Period",C.ink,8,"middle","600");
  ln(svg,66,58,84,58,C.coral,3);txt(svg,89,61,"Treated · observed",C.coral,8);
  ln(svg,234,58,252,58,C.blue,3);txt(svg,257,61,"Comparison · observed",C.blue,8);
  ln(svg,435,58,453,58,C.coral,2.5,"6 4");txt(svg,458,61,"Treated if untreated (counterfactual)",C.coral,8);
  const interventionX=(x0+x1)/2;ln(svg,interventionX,yTop,interventionX,yBottom,C.gold,1.5,"5 4");txt(svg,interventionX,77,"Treatment",C.gold,8,"middle","700");
  ln(svg,x0,Y(preC),x1,Y(postC),C.blue,3);ln(svg,x0,Y(preT),x1,Y(postT),C.coral,3);ln(svg,x0,Y(preT),x1,Y(postCounterfactual),C.coral,2.5,"6 4");
  circle(svg,x0,Y(preT),5,C.coral);circle(svg,x1,Y(postT),5,C.coral);circle(svg,x0,Y(preC),5,C.blue);circle(svg,x1,Y(postC),5,C.blue);circle(svg,x1,Y(postCounterfactual),5,C.white,C.coral);
  txt(svg,x0-9,Y(preT)-7,fmt(preT,1),C.coral,8,"end","700");txt(svg,x0-9,Y(preC)+12,fmt(preC,1),C.blue,8,"end","700");
  txt(svg,x1+9,Y(postT)-6,fmt(postT,1),C.coral,8,"start","700");txt(svg,x1+9,Y(postCounterfactual)-7,`${fmt(postCounterfactual,1)} · unobserved`,C.coral,8,"start","700");txt(svg,x1+9,Y(postC)+12,fmt(postC,1),C.blue,8,"start","700");
  const treatedChange=postT-preT,comparisonChange=postC-preC,did=treatedChange-comparisonChange;
  txt(svg,313,Y((preT+postT)/2)-7,`Treated change ΔT = ${fmt(treatedChange,1)}`,C.coral,8,"middle","700");txt(svg,313,198,`Comparison change ΔC = ${fmt(comparisonChange,1)}`,C.blue,8,"middle","700");
  const yObserved=Y(postT),yCounterfactual=Y(postCounterfactual);ln(svg,gapX,yObserved,gapX,yCounterfactual,C.mint,2);ln(svg,gapX-5,yObserved,gapX+5,yObserved,C.mint,2);ln(svg,gapX-5,yCounterfactual,gapX+5,yCounterfactual,C.mint,2);txt(svg,gapX+10,(yObserved+yCounterfactual)/2+3,`DiD = ${fmt(did,1)}`,C.mint,8,"start","700");
  txt(svg,390,258,`DiD = (Tpost − Tpre) − (Cpost − Cpre) = ${fmt(did,1)} outcome units`,C.ink,8,"middle","700");
  metric(r,"Treated change ΔT",`${fmt(treatedChange,2)} units`);metric(r,"Comparison change ΔC",`${fmt(comparisonChange,2)} units`);metric(r,"DiD contrast ΔT − ΔC",`${fmt(did,2)} units`);metric(r,"Stated treatment effect",`${fmt(tau,2)} units`);metric(r,"Trend departure",`${fmt(violation,2)} units`);
  explanation(e,"The solid endpoints are the two observed means for each group; the dashed open point is the treated group’s unobserved post-period outcome without treatment, projected using the comparison-group change. DiD subtracts the comparison change from the treated change. It identifies the stated effect only when parallel trends holds; the slider adds a violation, so the contrast becomes effect + departure.");
