function drawRDD(svg:SVGSVGElement,v:Values,r:HTMLElement,e:HTMLElement){
  frame(svg,"Local comparison around an assignment threshold","Synthetic observations · local trends with a treatment jump");
  const jump=v.jump??1.5,bw=v.bandwidth??.7,rng=rngFactory(404),points:Array<{x:number,y:number,inside:boolean}>=[];
  for(let i=0;i<48;i++){const x=-.96+i*.04,y=3+1.1*x+(x>=0?jump:0)+gauss(rng)*.6;points.push({x,y,inside:Math.abs(x)<=bw});}
  const extent=Math.max(1.15,bw+.15),xmin=-extent,xmax=extent,fit=[3-1.1*bw,3+1.1*bw+jump],allY=[...points.map(p=>p.y),...fit],pad=Math.max(.35,(Math.max(...allY)-Math.min(...allY))*.08),ymin=Math.min(0,Math.floor((Math.min(...allY)-pad)*2)/2),ymax=Math.max(8,Math.ceil((Math.max(...allY)+pad)*2)/2),yTicks=Array.from({length:5},(_,i)=>ymin+(ymax-ymin)*i/4),{X,Y}=axes(svg,xmin,xmax,ymin,ymax,[-bw,0,bw],yTicks,"Running variable (score units)","Outcome (illustrative units)");
  ln(svg,X(0),Y(ymin),X(0),Y(ymax),C.gold,2,"5 4");for(const point of points)circle(svg,X(point.x),Y(point.y),point.inside?3.5:2.5,point.inside?(point.x<0?C.blue:C.coral):"#b8c1cb");
  const left:Array<[number,number]>=[],right:Array<[number,number]>=[];for(let i=0;i<=24;i++){const x=-bw+i*bw/24;left.push([X(x),Y(3+1.1*x)]);right.push([X(x),Y(3+1.1*x+jump)]);}path(svg,left,C.blue,2.5);path(svg,right,C.coral,2.5);
  ln(svg,X(-bw),Y(ymin),X(-bw),Y(ymax),C.mint,1,"4 4");ln(svg,X(bw),Y(ymin),X(bw),Y(ymax),C.mint,1,"4 4");metric(r,"Threshold jump set",fmt(jump),"outcome units");metric(r,"Local bandwidth",fmt(bw),"score units");metric(r,"Comparison","Near cutoff");metric(r,"Estimate scope","Local");explanation(e,"The colored points inside the selected window inform the local comparison. The plotted axes expand to include the selected bandwidth and fitted values. Interpretation requires continuity of potential outcomes and no precise sorting around the cutoff; the estimate applies near the threshold, not automatically to everyone.");
}

function drawPanel(svg:SVGSVGElement,v:Values,r:HTMLElement,e:HTMLElement){
  frame(svg,"First differences remove a shared period shock","Illustrative group means · a three-period DiD contrast, not a fitted panel regression");
  const tau=v.effect??1.5,shock=v.commonShock??1,preT=3,preC=1.4,tT=[preT,preT+shock,preT+2*shock+tau],tC=[preC,preC+shock,preC+2*shock],all=[...tT,...tC],pad=.8,ymin=Math.floor((Math.min(...all)-pad)*2)/2,ymax=Math.ceil((Math.max(...all)+pad)*2)/2,yTicks=Array.from({length:5},(_,i)=>ymin+(ymax-ymin)*i/4),{X,Y}=axes(svg,1,3,ymin,ymax,[1,2,3],yTicks,"Period (1–2 = pre; 3 = post)","Outcome (illustrative units)");
  path(svg,tT.map((y,i)=>[X(i+1),Y(y)]),C.coral,3);path(svg,tC.map((y,i)=>[X(i+1),Y(y)]),C.blue,3);for(let i=0;i<3;i++){circle(svg,X(i+1),Y(tT[i]),5,C.coral);circle(svg,X(i+1),Y(tC[i]),5,C.blue);}txt(svg,X(1),Y(preT)-12,"Treated",C.coral,9,"middle","700");txt(svg,X(1),Y(preC)-12,"Comparison",C.blue,9,"middle","700");ln(svg,X(2.5),Y(ymin),X(2.5),Y(ymax),C.gold,1.5,"5 4");txt(svg,X(2.5)+5,Y(ymax)-6,"Treatment begins",C.gold,8,"start","700");
  const treatedChange=tT[2]-tT[0],comparisonChange=tC[2]-tC[0],did=treatedChange-comparisonChange;metric(r,"Treated change (period 1→3)",fmt(treatedChange),"outcome units");metric(r,"Comparison change (period 1→3)",fmt(comparisonChange),"outcome units");metric(r,"Difference in changes (DiD)",fmt(did),"outcome units");metric(r,"Common shock per period",fmt(shock),"outcome units");explanation(e,"Periods 1–2 are pre-treatment and period 3 is post-treatment. A shared shock changes both groups by the same amount each period; the treatment effect appears only in period 3. From period 1 to 3, the treated group changes by 2 × shock + effect and the comparison group by 2 × shock, so their difference is the effect under parallel trends and no anticipation. This is a group-mean illustration, not an estimated individual-level fixed-effects coefficient.");
}
function drawCluster(svg:SVGSVGElement,v:Values,r:HTMLElement,e:HTMLElement){
  frame(svg,"Within-cluster correlation reduces independent information","Bars compare standard-error multipliers (×) · equal cluster size m = 20");const g=Math.max(4,Math.round(v.clusters??12)),rho=Math.max(0,Math.min(.9,v.icc??.2)),m=20,de=1+(m-1)*rho,infl=Math.sqrt(de);const x0=125;txt(svg,60,92,"Naive SE",C.blue,10);bar(svg,x0,72,100,22,C.blue);txt(svg,x0+110,88,"1.00×",C.blue,10,"start","700");txt(svg,60,136,"Cluster-aware",C.coral,10);bar(svg,x0,116,100*infl,22,C.coral);txt(svg,x0+110*infl,132,`${fmt(infl,2)}×`,C.coral,10,"start","700");const shown=Math.min(g,8);for(let i=0;i<shown;i++){const x=x0+i*70,y=174;svg.appendChild(el("rect",{x:x-22,y:y-17,width:48,height:34,rx:8,fill:i%2?"#fff1ed":"#eef4fb",stroke:i%2?C.coral:C.blue}));for(let j=0;j<3;j++)circle(svg,x-10+j*10,y,3,i%2?C.coral:C.blue);}txt(svg,681,185,`${g} clusters`,C.muted,9,"end","600");const neff=g*m/de;metric(r,"Clusters",String(g));metric(r,"Individuals (illustrative)",String(g*m));metric(r,"ICC ρ",fmt(rho));metric(r,"Approx. SE inflation",`${fmt(infl,2)}×`,`same factor for fixed m=20 and ICC`);metric(r,"Approx. effective n",fmt(neff,0));explanation(e,"This equal-size approximation illustrates why within-cluster dependence can widen uncertainty. A small number of clusters needs special care; robust standard errors do not fix bias or create more independent assignment units.");
}
